// The top-left "you are here" location crumb (#3036) — the sub-page detail appended after the
// Workspace name (from `registry.ts`) in the titlebar (`App.tsx` → `Titlebar`). Pure + unit-tested so
// EVERY navigable page is reflected, not just a few.
//
// Every workspace's active page IS in the store: an uncontrolled `<Screen>` persists it at
// `activePageTab[pageKey]` (`usePageTabs`), the controlled ones use a dedicated field
// (`projectsPageMode` / `githubTab` / `settingsSection`), and the console uses its own tab array.
//
// The page-label maps below MIRROR each feature's TabItem labels (glance `GLANCE_TABS`, skills
// `SKILL_TABS`, automations `defs`, logs `logDefs`, github `GITHUB_TABS`, planner
// `PROJECT_MODES`, settings `SECTIONS`). They live here (not imported) so the shell doesn't reach into
// every feature's internals; an id with no entry Title-Cases gracefully, so a newly-added tab is still
// labeled (never blank), just less pretty than a curated name.

import { workspaceLabel, type Workspace } from "@/app/registry";

/** Title-case a page id as a graceful fallback for an unmapped tab: `hook-analytics` → `Hook Analytics`. */
export function titleCasePageId(id: string): string {
  return id.split(/[-_]/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
}

/** Per-workspace page-id → label for the UNCONTROLLED Screens (active id in `activePageTab[pageKey]`). */
const PAGES: Partial<Record<Workspace, Record<string, string>>> = {
  glance:     { network: "Network", fleet: "Fleet" },
  logs:       { activity: "Activity", waiting: "Waiting", skills: "Skills", sessions: "Sessions", cost: "Cost", automations: "Automations", streams: "Streams" },
  // Memory's pages are the GRAPH plus one per memory kind. Mapped rather than Title-Cased from the id
  // (which is what this did first): the kind ids are singular — `lesson` — while the pages read as
  // plurals, and `note` reads as "Unclassified" because it is the absence of a kind rather than one.
  // The parity is pinned by a test against the feature's own `TAB_LABEL`, so the two cannot drift.
  memory:     { graph: "Graph", lesson: "Lessons", highlight: "Highlights", record: "Records", ambient: "Ambient", note: "Unclassified" },
};
/**
 * A graph WORKSPACE → the `crumbEntity` key the page reports under
 * (`five-graphs-become-rail-workspaces`).
 *
 * Needed because the two vocabularies are NOT the same. Each graph calls `useCrumbEntity` with its
 * historical PAGE id, and one of those differs from the workspace key: the Design Studio reports
 * under `designs` while its Workspace is `components` (the tab id was the feature name, the label was
 * "Components", #2818). Reading `crumbEntity[workspace]` directly would therefore work for four
 * graphs and silently show nothing for the fifth — the kind of near-miss that reads as "the crumb is
 * just like that" rather than as a bug.
 *
 * `data` is absent on purpose: that page reports no entity yet, so there is nothing to key.
 */
const GRAPH_CRUMB_KEY: Partial<Record<Workspace, string>> = {
  components: "designs",
  teams: "teams",
  algorithms: "algorithms",
  sounds: "sounds",
};

/** Settings section (`settingsSection`) → label (mirrors `SECTIONS`). */
const SETTINGS_SECTIONS: Record<string, string> = { general: "General", planner: "Planner", skills: "Skills", automations: "Automations", mcp: "MCP", github: "GitHub", security: "Security" };

/** The `activePageTab` key when it differs from the Workspace key. EMPTY now — automations was
 *  the only one, and that workspace is retired. Kept because the lookup below reads it and a
 *  future workspace may need it again. */
const PAGE_KEY: Partial<Record<Workspace, string>> = {};
/** The default first tab per uncontrolled workspace — so the crumb shows the current page even before
 *  the user has ever selected one (`activePageTab` is empty until the first click). Mirrors each feature's
 *  first `TabItem` id. */
const DEFAULT_PAGE: Partial<Record<Workspace, string>> = {
  glance: "network", logs: "activity", memory: "graph",
};

const label = (map: Record<string, string>, id: string | undefined): string =>
  id ? (map[id] ?? titleCasePageId(id)) : "";

/** The store fields the crumb reads — kept explicit (a subset of `AppStore`) so it's trivially testable. */
export interface CrumbState {
  activeWorkspace: Workspace;
  activePageTab: Record<string, string>;
  /** The navigated ENTITY per graph, keyed by page id (`glance`/`teams`/`designs`/`algorithms`),
   *  reported by each graph via `useCrumbEntity` (#3041). Appended after the page name. */
  crumbEntity: Record<string, string>;
  projectsPageMode: string;
  projectsView: string;
  settingsSection: string;
  /** The active console tab's name (`tabs[activeTabIdx]?.name`). */
  consoleTab?: string;
  focusedAgentName?: string;
}

/**
 * The full "you are here" crumb: the Workspace's canonical name (`registry.ts`) followed by its active
 * PAGE label — and, where meaningful, one more detail (the focused console agent, the planning
 * session). Every workspace's page is reflected. Parts are joined with " — ".
 */
export function locationCrumb(s: CrumbState): string {
  const w = s.activeWorkspace;
  const parts: string[] = [workspaceLabel(w)];
  switch (w) {
    case "console":
      if (s.consoleTab) parts.push(s.consoleTab);
      if (s.focusedAgentName) parts.push(s.focusedAgentName);
      break;
    case "glance":
      parts.push(label(PAGES.glance ?? {}, s.activePageTab.glance ?? DEFAULT_PAGE.glance));
      if (s.crumbEntity.glance) parts.push(s.crumbEntity.glance); // the drilled project
      break;
    case "logs":
      parts.push(label(PAGES[w] ?? {}, s.activePageTab[PAGE_KEY[w] ?? w] ?? DEFAULT_PAGE[w]));
      break;
    case "memory":
      parts.push(label(PAGES[w] ?? {}, s.activePageTab[w] ?? DEFAULT_PAGE[w]));
      break;
    case "settings":
      parts.push(label(SETTINGS_SECTIONS, s.settingsSection));
      break;
    case "components":
    case "teams":
    case "algorithms":
    case "data":
    case "sounds": {
      // The five graphs (`five-graphs-become-rail-workspaces`). The Workspace NAME is already in
      // `parts[0]`; this adds the active TAB and then the navigated entity.
      //
      // The tab is Title-Cased from its id rather than mapped: unlike every other workspace here, these
      // vocabularies are DATA — the languages the knowledge graph holds, the sound kits, the teams — so
      // a curated label map would be a second copy that goes stale the moment the data changes, and a
      // stale map shows the wrong name rather than an ugly one. `titleCasePageId` already exists for
      // exactly this "labelled, never blank" case.
      //
      // Teams' overview tab is skipped: its id is `teams`, so it would render "Teams — Teams".
      const tab = s.activePageTab[w];
      if (tab && !(w === "teams" && tab === "teams")) parts.push(titleCasePageId(tab));
      // The entity — the active kit, team or language the page itself reports. Before the promotion
      // this came through the `projects` case reading `crumbEntity[projectsPageMode]`; that path is
      // dead now, so without this the crumb would quietly stop naming what you are looking at.
      const entity = s.crumbEntity[GRAPH_CRUMB_KEY[w] ?? w];
      if (entity) parts.push(entity);
      break;
    }
  }
  return parts.filter(Boolean).join(" — ");
}
